using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json.Linq;
public static class F1Polish {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";
 static Vector3 V(JToken a)=>new Vector3((float)a[0],(float)a[1],(float)a[2]);
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var p=JObject.Parse(File.ReadAllText(R+"/SourceAssets/F1_FullFloor/resolved.json"));var root=GameObject.Find("1F_AbandonedFactory");
  foreach(var q in (JObject)p["models"]){if(q.Value["reuse"]!=null)continue;var mi=(ModelImporter)AssetImporter.GetAtPath((string)q.Value["asset"]);mi.importAnimation=false;mi.animationType=ModelImporterAnimationType.None;mi.isReadable=false;mi.importNormals=ModelImporterNormals.Import;mi.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;mi.materialLocation=ModelImporterMaterialLocation.InPrefab;foreach(string name in q.Value["materials"].Select(v=>(string)v).Distinct())mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),name),AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/"+name+".mat"));mi.SaveAndReimport();}
  foreach(var q in p["placements"]){if(GameObject.Find((string)q["name"]))continue;var parent=root.transform.Find("1F_"+(string)q["room"]);var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>((string)q["asset"]),parent);g.name=(string)q["name"];g.transform.SetPositionAndRotation(V(q["position"]),Quaternion.Euler(0,(float)q["yaw"],0));var rs=g.GetComponentsInChildren<Renderer>();var lod=g.GetComponent<LODGroup>()??g.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.2f,rs.Where(r=>r.name.EndsWith("LOD0")).ToArray()),new LOD(.065f,rs.Where(r=>r.name.EndsWith("LOD1")).ToArray()),new LOD(.008f,rs.Where(r=>r.name.EndsWith("LOD2")).ToArray())});lod.RecalculateBounds();var c=g.AddComponent<BoxCollider>();c.center=V(q["center"]);c.size=V(q["size"]);}
  // World-space operational lettering must obey depth and face its room.
  string path=E+"Materials/F1_SignText.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Unlit")){name="F1_SignText"};mat.SetTexture("_BaseMap",Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf").material.mainTexture);mat.SetColor("_BaseColor",new Color(.83f,.85f,.75f));mat.SetFloat("_Surface",1);mat.SetFloat("_Blend",0);mat.SetInt("_SrcBlend",(int)BlendMode.SrcAlpha);mat.SetInt("_DstBlend",(int)BlendMode.OneMinusSrcAlpha);mat.SetInt("_ZWrite",0);mat.SetFloat("_Cull",2);mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");mat.renderQueue=3000;AssetDatabase.CreateAsset(mat,path);}
  foreach(var t in root.GetComponentsInChildren<TextMesh>()){if(t.GetComponent<Renderer>().sharedMaterial!=mat){t.transform.Rotate(0,180,0);t.characterSize*=.62f;}t.GetComponent<Renderer>().sharedMaterial=mat;}
  // A local exterior ground removes the sky void beyond the windows; accessible paving stays on its own collider.
  if(!root.transform.Find("ExteriorGround")){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name="ExteriorGround";g.transform.SetParent(root.transform,false);g.transform.position=new Vector3(0,-.35f,0);g.transform.localScale=new Vector3(320,.3f,320);UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/F1M_Floor.mat");}
  // Gable end triangles originally faced outward only; add the inner skin without duplicated coplanar faces.
  foreach(string id in new[]{"C01","C02"}){var r=p["rooms"].First(q=>(string)q["id"]==id);float x=(float)r["x"],z=(float)r["z"],w=(float)r["w"],d=(float)r["d"],h=(float)r["h"];var roof=GameObject.Find("F1_"+id+"_Roof");var mats=roof.GetComponentInChildren<Renderer>().sharedMaterials;foreach(var m in mats)if(m.name=="F1M_Coat")m.SetFloat("_Cull",0);}
  foreach(var t in root.GetComponentsInChildren<Transform>(true))if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);foreach(var c in t.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}
  Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s);EditorSceneManager.OpenScene(s.path);return new{placements=p["placements"].Count(),saved=true};
 }
}
